import React, { useState } from 'react';
import { Routes, Route, NavLink, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
    LayoutDashboard, Truck, Package, DollarSign,
    Menu, X, Bell, Moon, Sun, User, MapPin, FileText
} from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../context/AuthContext';
import DispatchOverview from './DispatchOverview';
import AssignedDeliveries from './AssignedDeliveries';
import DeliveryHistory from './DeliveryHistory';
import DispatchEarnings from './DispatchEarnings';
import DispatchDetails from './DispatchDetails';

const navigation = [
    { path: '/dispatch/dashboard', icon: LayoutDashboard, label: 'Overview', end: true },
    { path: '/dispatch/deliveries', icon: Truck, label: 'Deliveries' },
    { path: '/dispatch/history', icon: FileText, label: 'History' },
    { path: '/dispatch/earnings', icon: DollarSign, label: 'Earnings' },
];

const DispatchDashboard = () => {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const location = useLocation();
    const { isDark, toggleTheme } = useTheme();
    const { user, logout } = useAuth();

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
            {/* Mobile Sidebar */}
            <AnimatePresence>
                {sidebarOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50 z-40 lg:hidden"
                        onClick={() => setSidebarOpen(false)}
                    />
                )}
            </AnimatePresence>

            {/* Sidebar */}
            <motion.aside
                initial={false}
                animate={{ x: sidebarOpen ? 0 : -320 }}
                className="fixed top-0 left-0 z-50 h-full w-64 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 lg:translate-x-0 lg:static lg:z-auto"
            >
                <div className="flex flex-col h-full">
                    <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-2">
                            <Truck className="h-8 w-8 text-teal-600" />
                            <span className="font-bold text-gray-900 dark:text-white">DispatchPro</span>
                        </div>
                        <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
                            <X className="h-5 w-5 text-gray-500" />
                        </button>
                    </div>

                    <nav className="flex-1 p-4 space-y-1">
                        {navigation.map((item) => (
                            <NavLink
                                key={item.path}
                                to={item.path}
                                end={item.end}
                                onClick={() => setSidebarOpen(false)}
                                className={({ isActive }) => `
                  flex items-center gap-3 px-3 py-2 rounded-lg transition-colors
                  ${isActive
                                        ? 'bg-teal-50 text-teal-700 dark:bg-teal-900/20 dark:text-teal-400'
                                        : 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
                                    }
                `}
                            >
                                <item.icon className="h-5 w-5" />
                                {item.label}
                            </NavLink>
                        ))}
                    </nav>

                    <div className="p-4 border-t border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-3">
                            <div className="h-10 w-10 rounded-full bg-teal-100 dark:bg-teal-900/30 flex items-center justify-center">
                                <User className="h-5 w-5 text-teal-600" />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                                    {user?.firstName} {user?.lastName}
                                </p>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Dispatch Partner</p>
                            </div>
                        </div>
                        <button
                            onClick={logout}
                            className="mt-3 w-full px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                        >
                            Sign Out
                        </button>
                    </div>
                </div>
            </motion.aside>

            {/* Main Content */}
            <div className="lg:pl-64">
                <header className="sticky top-0 z-30 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
                    <div className="flex items-center justify-between px-4 h-16">
                        <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
                            <Menu className="h-5 w-5 text-gray-500" />
                        </button>
                        <div className="flex items-center gap-4 ml-auto">
                            <button className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
                                <Bell className="h-5 w-5 text-gray-500" />
                            </button>
                            <button onClick={toggleTheme} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
                                {isDark ? <Sun className="h-5 w-5 text-gray-500" /> : <Moon className="h-5 w-5 text-gray-500" />}
                            </button>
                        </div>
                    </div>
                </header>

                <main className="p-6">
                    <Routes>
                        <Route index element={<DispatchOverview />} />
                        <Route path="deliveries" element={<AssignedDeliveries />} />
                        <Route path="history" element={<DeliveryHistory />} />
                        <Route path="earnings" element={<DispatchEarnings />} />
                        <Route path="details/:id" element={<DispatchDetails />} />
                    </Routes>
                </main>
            </div>
        </div>
    );
};

export default DispatchDashboard;
